import { clamp, ease } from '@/lib/easing';
import { CYCLE_MOTION } from '@/lib/constants';

export type PhoneEntryState = 'upcoming' | 'active' | 'past';

export interface PhoneSequenceState {
  statusOpacity: number;
  headerOpacity: number;
  headerOffset: number;
  headerRuleProgress: number;
  entryOpacities: number[];
  entryOffsets: number[];
  rowScales: number[];
  iconScales: number[];
  entryStates: PhoneEntryState[];
  activeIndex: number;
  lineProgress: number;
}

export interface ClockSequenceState {
  displayProgress: number;
  ringAmount: number;
  flashAmount: number;
  faceIn: number;
  hold0659: number;
  flipMinuteOnes: number;
  flipMinuteTens: number;
  flipHourOnes: number;
  settle0700: number;
}

export interface LaptopSequenceState {
  screenReveal: number;
  screenWake: number;
  glowAmount: number;
  screenMessageOpacity: number;
  screenMessageHold: number;
  planeMatchProgress: number;
  takeoverOpacity: number;
  screenRedAmount: number;
  hardwareFade: number;
}

function reveal(progress: number, start: number, duration: number): number {
  return ease(clamp((progress - start) / duration, 0, 1));
}

function mixValue(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

export function getPhoneSequenceState(
  progress: number,
  itemCount: number,
  reducedMotion = false,
): PhoneSequenceState {
  if (reducedMotion) {
    return {
      statusOpacity: 1,
      headerOpacity: 1,
      headerOffset: 0,
      headerRuleProgress: 1,
      entryOpacities: Array.from({ length: itemCount }, () => 1),
      entryOffsets: Array.from({ length: itemCount }, () => 0),
      rowScales: Array.from({ length: itemCount }, () => 1),
      iconScales: Array.from({ length: itemCount }, () => 1),
      entryStates: Array.from({ length: itemCount }, (_, index) =>
        index === itemCount - 1 ? 'active' : 'past',
      ),
      activeIndex: itemCount - 1,
      lineProgress: 1,
    };
  }

  const statusOpacity = reveal(progress, 0.16, 0.07);
  const headerOpacity = reveal(progress, 0.24, 0.08);
  const headerOffset = (1 - headerOpacity) * 16;
  const revealStart = CYCLE_MOTION.phone.contentRevealStart;
  const revealEnd = CYCLE_MOTION.phone.contentRevealEnd;
  const revealRange = revealEnd - revealStart;
  const headerRuleProgress = clamp((progress - revealStart) / revealRange, 0, 1);

  const entryOpacities: number[] = [];
  const entryOffsets: number[] = [];
  const rowScales: number[] = [];
  const iconScales: number[] = [];
  let activeIndex = -1;

  for (let index = 0; index < itemCount; index += 1) {
    const rowStart = revealStart + (index / itemCount) * revealRange;
    const opacity = reveal(progress, rowStart, 0.065);
    entryOpacities.push(opacity);
    entryOffsets.push((1 - opacity) * 18);
    rowScales.push(0.92 + opacity * 0.08);
    iconScales.push(0.7 + opacity * 0.3);

    if (opacity >= 0.94) {
      const nextStart = revealStart + ((index + 1) / itemCount) * revealRange;
      const nextOpacity =
        index < itemCount - 1 ? reveal(progress, nextStart, 0.065) : 0;

      if (nextOpacity < 0.42 || index === itemCount - 1) {
        activeIndex = index;
      }
    }
  }

  const entryStates = entryOpacities.map((opacity, index) => {
    if (index === activeIndex) return 'active';
    if (activeIndex > index || opacity >= 0.92) return 'past';
    return 'upcoming';
  });

  return {
    statusOpacity,
    headerOpacity,
    headerOffset,
    headerRuleProgress,
    entryOpacities,
    entryOffsets,
    rowScales,
    iconScales,
    entryStates,
    activeIndex,
    lineProgress: headerRuleProgress,
  };
}

export function getClockSequenceState(
  progress: number,
  reducedMotion = false,
): ClockSequenceState {
  const displayProgress = reveal(progress, 0.02, reducedMotion ? 0.07 : 0.1);
  const faceIn = displayProgress;
  const hold0659 = reveal(progress, 0.14, reducedMotion ? 0.05 : 0.08);
  const flipMinuteOnes = reveal(
    progress,
    reducedMotion ? 0.48 : 0.52,
    reducedMotion ? 0.05 : 0.08,
  );
  const flipMinuteTens = reveal(
    progress,
    reducedMotion ? 0.62 : 0.66,
    reducedMotion ? 0.05 : 0.07,
  );
  const flipHourOnes = reveal(
    progress,
    reducedMotion ? 0.74 : 0.78,
    reducedMotion ? 0.06 : 0.075,
  );
  const settle0700 = reveal(
    progress,
    reducedMotion ? 0.84 : 0.88,
    reducedMotion ? 0.08 : 0.08,
  );

  const ringLift = reveal(progress, 0.5, reducedMotion ? 0.08 : 0.1);
  const ringTail = 1 - reveal(progress, 0.94, reducedMotion ? 0.05 : 0.07);
  const ringAmount = ringLift * ringTail * (reducedMotion ? 0.28 : 1);
  const flashAmount =
    reveal(progress, 0.56, reducedMotion ? 0.06 : 0.075) *
    (1 - reveal(progress, 0.94, reducedMotion ? 0.05 : 0.07)) *
    (reducedMotion ? 0.5 : 1);

  return {
    displayProgress,
    ringAmount,
    flashAmount,
    faceIn,
    hold0659,
    flipMinuteOnes,
    flipMinuteTens,
    flipHourOnes,
    settle0700,
  };
}

export function getLaptopSequenceState(
  progress: number,
  _rowCount: number,
  reducedMotion = false,
): LaptopSequenceState {
  void _rowCount;
  if (reducedMotion) {
    return {
      screenReveal: 1,
      screenWake: 0.78,
      glowAmount: 0.3,
      screenMessageOpacity: 1,
      screenMessageHold: 1,
      planeMatchProgress: 0,
      takeoverOpacity: 0,
      screenRedAmount: 0.36,
      hardwareFade: 1,
    };
  }

  const glowOpenEnd = CYCLE_MOTION.laptop.glowOpenEnd;
  const headlineHoldEnd = CYCLE_MOTION.laptop.headlineHoldEnd;
  const screenPushStart = CYCLE_MOTION.laptop.screenPushStart;
  const redTakeoverStart = CYCLE_MOTION.laptop.redTakeoverStart;
  const redTakeoverEnd = CYCLE_MOTION.laptop.redTakeoverEnd;
  const screenReveal = reveal(progress, 0.02, 0.12);
  const screenWake = mixValue(
    0.12,
    1,
    reveal(progress, 0.02, glowOpenEnd - 0.02),
  );
  const glowLift = reveal(progress, 0.04, 0.2);
  const glowTail = 1 - reveal(progress, headlineHoldEnd, 0.18);
  const glowAmount =
    glowLift *
    mixValue(1, 0.28, reveal(progress, headlineHoldEnd, 0.18)) *
    glowTail;

  const screenMessageOpacity =
    reveal(progress, glowOpenEnd, 0.08) *
    (1 - reveal(progress, screenPushStart, redTakeoverStart - screenPushStart));
  const screenMessageHold =
    reveal(progress, glowOpenEnd + 0.04, 0.08) *
    (1 - reveal(progress, screenPushStart, 0.06));
  const planeMatchProgress = reveal(
    progress,
    screenPushStart,
    Math.max(redTakeoverStart - screenPushStart, 0.001),
  );

  let screenRedAmount: number;
  if (progress < glowOpenEnd) {
    screenRedAmount = mixValue(
      0.06,
      0.24,
      reveal(progress, 0.02, glowOpenEnd - 0.02),
    );
  } else if (progress < headlineHoldEnd) {
    screenRedAmount = mixValue(
      0.24,
      0.38,
      reveal(progress, glowOpenEnd, headlineHoldEnd - glowOpenEnd),
    );
  } else if (progress < redTakeoverStart) {
    screenRedAmount = mixValue(
      0.38,
      0.68,
      reveal(progress, screenPushStart, redTakeoverStart - screenPushStart),
    );
  } else {
    screenRedAmount = mixValue(
      0.68,
      1,
      reveal(progress, redTakeoverStart, redTakeoverEnd - redTakeoverStart),
    );
  }

  const takeoverOpacity = reveal(
    progress,
    redTakeoverStart,
    Math.max(redTakeoverEnd - redTakeoverStart, 0.001),
  );
  const hardwareFade = 1 - takeoverOpacity;

  return {
    screenReveal,
    screenWake,
    glowAmount,
    screenMessageOpacity,
    screenMessageHold,
    planeMatchProgress,
    takeoverOpacity,
    screenRedAmount,
    hardwareFade,
  };
}
