function toMinutes(entry: TimeSequenceEntry): number {
  let hour = entry.h;
  if (entry.ampm === 'PM' && hour !== 12) hour += 12;
  if (entry.ampm === 'AM' && hour === 12) hour = 0;
  return hour * 60 + entry.m;
}

function interpolateTime(
  sequence: readonly TimeSequenceEntry[],
  progress: number,
): { h: number; m: number; ampm: 'AM' | 'PM' } {
  const count = sequence.length;
  if (count === 0) return { h: 0, m: 0, ampm: 'AM' };

  const t = clamp(progress, 0, 1);
  const position = t * (count - 1);
  const low = Math.floor(position);
  const high = Math.min(low + 1, count - 1);
  const fraction = position - low;

  const minsLow = toMinutes(sequence[low]);
  const minsHigh = toMinutes(sequence[high]);
  const totalMinutes = minsLow + (minsHigh - minsLow) * fraction;
  const rounded = Math.floor(totalMinutes);
  const hour24 = Math.floor(rounded / 60) % 24;
  const minute = rounded % 60;
  const ampm: 'AM' | 'PM' = hour24 >= 12 ? 'PM' : 'AM';
  let hour = hour24 % 12;
  if (hour === 0) hour = 12;

  return { h: hour, m: minute, ampm };
}

function formatInterpolatedTime(time: { h: number; m: number; ampm: 'AM' | 'PM' }) {
  return `${time.h}:${String(time.m).padStart(2, '0')} ${time.ampm}`;
}

function selectTransform(phase: PhaseName) {
  return (state: ReturnType<typeof useScrollStore.getState>) =>
    state[`${phase}Transform` as `${PhaseName}Transform`] as PhaseTransform;
}

function PhaseLayer({
  phase,
  children,
  className = '',
  reducedMotion = false,
}: {
  phase: PhaseName;
  children: ReactNode;
  className?: string;
  reducedMotion?: boolean;
}) {
  const transform = useScrollStore(selectTransform(phase));
  const is3DPhase =
    phase === 'phone' ||
    phase === 'clock' ||
    phase === 'laptop';

  return (
    <div
      className={`absolute inset-0 ${className}`}
      style={{
        opacity: transform.opacity,
        transform:
          reducedMotion || is3DPhase
            ? 'none'
            : `translateY(${transform.yShift}px) scale(${transform.scale})`,
        filter:
          reducedMotion || is3DPhase || transform.blur <= 0.1
            ? 'none'
            : `blur(${transform.blur}px)`,
        pointerEvents: transform.opacity > 0.01 ? 'auto' : 'none',
        willChange:
          reducedMotion || is3DPhase ? 'opacity' : 'opacity, transform, filter',
      }}
    >
      {children}
    </div>
  );
}

function staggerStyle(
  progress: number,
  delay: number,
  speed: number,
  reducedMotion: boolean,
): CSSProperties {
  if (reducedMotion) return {};

  const t = ease(clamp((progress - delay) * speed, 0, 1));
  return {
    opacity: t,
    transform: `translateY(${(1 - t) * 18}px)`,
    willChange: t > 0 && t < 1 ? 'opacity, transform' : 'auto',
  };
}

function slideXStyle(
  progress: number,
  delay: number,
  speed: number,
  fromX: number,
  reducedMotion: boolean,
): CSSProperties {
  if (reducedMotion) return {};

  const t = ease(clamp((progress - delay) * speed, 0, 1));
  return {
    opacity: t,
    transform: `translateX(${(1 - t) * fromX}px)`,
    willChange: t > 0 && t < 1 ? 'opacity, transform' : 'auto',
  };
}

function ClockDigits({
  timeLabel,
  accent = false,
}: {
  timeLabel: string;
  accent?: boolean;
}) {
  const [time, ampm = ''] = timeLabel.split(' ');
  const [hour = '', minute = '00'] = time.split(':');
  const hourDigits = hour.length === 1 ? ['', hour] : hour.split('');
  const minuteDigits = minute.split('');
  const digits = [...hourDigits, ...minuteDigits];

  return (
    <div className="flex items-end justify-center gap-2 md:gap-3">
      <div className="flex gap-1.5 md:gap-2">
        {digits.slice(0, 2).map((digit, index) => (
          <div
            key={`hour-${index}`}
            className="flex h-[4rem] w-[3rem] items-center justify-center rounded-[18px] border border-white/8 bg-[#11120f]/95 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)] md:h-[5rem] md:w-[4rem]"
          >
            <span
              className={`font-heading text-[2.4rem] font-bold leading-none md:text-[3.8rem] ${
                digit ? 'text-text-primary' : 'text-transparent'
              }`}
            >
              {digit || '0'}
            </span>
          </div>
        ))}
      </div>

      <span className="pb-2 font-heading text-[2.4rem] font-bold leading-none text-text-primary/85 md:text-[4rem]">
        :
      </span>

      <div className="flex gap-1.5 md:gap-2">
        {digits.slice(2).map((digit, index) => (
          <div
            key={`minute-${index}`}
            className="flex h-[4rem] w-[3rem] items-center justify-center rounded-[18px] border border-white/8 bg-[#11120f]/95 shadow-[inset_0_1px_0_rgba(255,255,255,0.04)] md:h-[5rem] md:w-[4rem]"
          >
            <span className="font-heading text-[2.4rem] font-bold leading-none text-text-primary md:text-[3.8rem]">
              {digit}
            </span>
          </div>
        ))}
      </div>

      <span
        className={`pb-2 font-mono text-[1.25rem] uppercase tracking-[0.2em] md:text-[1.55rem] ${
          accent ? 'text-accent/80' : 'text-text-primary/60'
        }`}
      >
        {ampm}
      </span>
    </div>
  );
}

function CycleAtmosphere() {
  const cycleProgress = useScrollStore((state) => state.cycleProgress);
  const amberStart = PHASES.handoff.in;
  const amberEnd = PHASES.clock.in;
  const morningStart = PHASES.clock.in + (PHASES.clock.out - PHASES.clock.in) * 0.5;
  const morningEnd = PHASES.laptop.in + (PHASES.laptop.out - PHASES.laptop.in) * 0.58;
  const resetStart =
    PHASES.workTransition.in + (PHASES.workTransition.out - PHASES.workTransition.in) * 0.75;
  const resetDuration = Math.max(PHASES.workTransition.out - resetStart, 0.001);

  const amber = ease(
    clamp((cycleProgress - amberStart) / Math.max(amberEnd - amberStart, 0.001), 0, 1),
  );
  const morning = ease(
    clamp(
      (cycleProgress - morningStart) /
        Math.max(morningEnd - morningStart, 0.001),
      0,
      1,
    ),
  );
  const reset = ease(clamp((cycleProgress - resetStart) / resetDuration, 0, 1));

  return (
    <div className="pointer-events-none absolute inset-0 overflow-hidden">
      <div
        className="absolute left-1/2 top-[18%] h-[40rem] w-[40rem] -translate-x-1/2 rounded-full blur-[120px]"
        style={{
          opacity: 0.18 + amber * 0.3 - reset * 0.18,
          background:
            'radial-gradient(circle, rgba(224,68,88,0.18) 0%, rgba(186,139,44,0.12) 32%, rgba(5,5,5,0) 72%)',
        }}
      />
      <div
        className="absolute left-[15%] top-[56%] h-[24rem] w-[24rem] rounded-full blur-[100px]"
        style={{
          opacity: 0.1 + amber * 0.16,
          background:
            'radial-gradient(circle, rgba(120,90,28,0.26) 0%, rgba(11,10,8,0) 72%)',
        }}
      />
      <div
        className="absolute right-[12%] top-[50%] h-[34rem] w-[34rem] rounded-full blur-[120px]"
        style={{
          opacity: morning * 0.55,
          background:
            'radial-gradient(circle, rgba(247,242,232,0.75) 0%, rgba(232,220,187,0.28) 38%, rgba(255,255,255,0) 74%)',
        }}
      />
      <div
        className="absolute inset-x-0 top-0 h-40"
        style={{
          opacity: 0.6,
          background:
            'linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0))',
        }}
      />
    </div>
  );
}

