function ClockContent({ reducedMotion }: { reducedMotion: boolean }) {
  const progress = useScrollStore((state) => state.clockProgress);
  const receiveIn = reducedMotion
    ? 1
    : ease(clamp(progress / CYCLE_MOTION.clock.receiveInEnd, 0, 1));
  const pillIn = reducedMotion
    ? 1
    : ease(
        clamp(
          (progress - CYCLE_MOTION.clock.pillInStart) /
            (CYCLE_MOTION.clock.pillInEnd - CYCLE_MOTION.clock.pillInStart),
          0,
          1,
        ),
      );
  const yieldT = reducedMotion
    ? 0
    : ease(
        clamp(
          (progress - CYCLE_MOTION.clock.yieldStart) /
            (CYCLE_MOTION.clock.yieldEnd - CYCLE_MOTION.clock.yieldStart),
          0,
          1,
        ),
      );

  return (
    <div className="relative flex h-full flex-col items-center justify-center px-6">
      <div className="pointer-events-none absolute inset-0">
        <div
          className="absolute left-1/2 top-[48%] h-[46rem] w-[46rem] max-h-[82vh] max-w-[82vw] rounded-full bg-[radial-gradient(circle,rgba(240,233,210,0.4),rgba(224,68,88,0.12)_28%,rgba(15,11,6,0)_70%)] blur-[120px]"
          style={{
            opacity: (0.3 + receiveIn * 0.7) * (1 - yieldT * 0.4),
            transform: `translate(-50%, -50%) scale(${0.94 + receiveIn * 0.06 - yieldT * 0.03})`,
          }}
        />
      </div>
      <div
        className="pointer-events-none absolute top-16 left-1/2 -translate-x-1/2 rounded-full border border-[#83713c]/18 bg-[#efe6d4]/10 px-4 py-2"
        style={{
          opacity: pillIn * (1 - yieldT * 0.35),
          transform: reducedMotion
            ? 'translateX(-50%)'
            : `translateX(-50%) translateY(${(1 - pillIn) * 14}px)`,
        }}
      >
        <span className="font-mono text-[10px] uppercase tracking-[0.24em] text-[#DEB42E]">
          {CYCLE_CLOCK.lead}
        </span>
      </div>
    </div>
  );
}

function LaptopSequenceLayer({
  canRender3D,
  reducedMotion,
  localizedEmails,
}: {
  canRender3D: boolean;
  reducedMotion: boolean;
  localizedEmails: typeof EMAIL_ENTRIES;
}) {
  const sequenceProgress = useScrollStore((state) => state.laptopProgress);
  const sequenceState = getLaptopSequenceState(
    sequenceProgress,
    localizedEmails.length,
    reducedMotion,
  );
  const labelIn = reducedMotion
    ? 1
    : ease(
        clamp(
          (sequenceProgress - CYCLE_MOTION.laptop.labelInStart) /
            (CYCLE_MOTION.laptop.labelInEnd - CYCLE_MOTION.laptop.labelInStart),
          0,
          1,
        ),
      );
  const planeMatch = reducedMotion ? 0 : sequenceState.planeMatchProgress;
  const sceneFade = reducedMotion ? 1 : 0.14 + sequenceState.hardwareFade * 0.86;
  const panelOpacity = reducedMotion ? 0 : sequenceState.takeoverOpacity;
  const panelWidth = 54 + panelOpacity * 46;
  const panelHeight = 34 + panelOpacity * 66;
  const panelRadius = 26 - panelOpacity * 26;
  const panelY = 51 - panelOpacity * 1.5;
  const panelScale = 0.985 + panelOpacity * 0.015;
  const sceneScale = 1 - planeMatch * 0.008 - panelOpacity * 0.012;
  const sceneLift = planeMatch * -3 - panelOpacity * 10;

  return (
    <div className="absolute inset-0">
      <div className="pointer-events-none absolute inset-0">
        <div
          className="absolute left-1/2 top-[50%] h-[60rem] w-[60rem] max-h-[92vh] max-w-[92vw] rounded-full blur-[130px]"
          style={{
            background:
              'radial-gradient(circle, rgba(255,244,232,0.52) 0%, rgba(226,96,110,0.18) 34%, rgba(255,255,255,0) 70%)',
            opacity:
              (0.08 + labelIn * 0.34 + sequenceState.glowAmount * 0.22) *
              (1 - sequenceState.takeoverOpacity * 0.64),
            transform: `translate(-50%, -50%) scale(${0.96 + labelIn * 0.04})`,
          }}
        />
      </div>

      <div
        className="absolute inset-0"
        style={{
          opacity: sceneFade,
          transform: reducedMotion
            ? 'none'
            : `scale(${sceneScale}) translateY(${sceneLift}px)`,
        }}
      >
        {canRender3D ? (
          <ErrorBoundary
            fallback={
              <LaptopFallback emails={localizedEmails} reducedMotion={reducedMotion} />
            }
          >
            <LaptopScene emails={localizedEmails} reducedMotion={reducedMotion} />
          </ErrorBoundary>
        ) : (
          <LaptopFallback emails={localizedEmails} reducedMotion={reducedMotion} />
        )}
      </div>

      <div className="pointer-events-none absolute inset-0 flex items-center justify-center overflow-hidden">
        <div
          className="absolute left-1/2 overflow-hidden border border-white/8 shadow-[0_24px_80px_rgba(20,4,8,0.24)]"
          style={{
            opacity: panelOpacity,
            width: `${panelWidth}%`,
            height: `${panelHeight}%`,
            top: `${panelY}%`,
            background:
              'radial-gradient(circle at 50% 24%, rgba(255,236,220,0.14) 0%, rgba(223,54,79,0.22) 20%, rgba(125,13,29,0.56) 52%, rgba(34,4,10,0.98) 100%)',
            borderRadius: `${panelRadius}px`,
            transform: `translate(-50%, -50%) scale(${panelScale})`,
          }}
        >
          <div
            className="absolute inset-0"
            style={{
              background:
                'linear-gradient(180deg, rgba(255,245,235,0.08), rgba(255,255,255,0.01) 18%, rgba(0,0,0,0) 34%, rgba(0,0,0,0.18) 100%)',
              opacity: 0.48 - panelOpacity * 0.12,
            }}
          />
        </div>
        <div
          className="absolute left-1/2 overflow-hidden rounded-[2rem] blur-[80px]"
          style={{
            opacity: panelOpacity * 0.7,
            width: `${panelWidth * 0.94}%`,
            height: `${panelHeight * 0.9}%`,
            top: `${panelY}%`,
            background:
              'radial-gradient(circle at 50% 30%, rgba(255,240,228,0.12) 0%, rgba(229,74,97,0.18) 30%, rgba(148,20,37,0.08) 65%, rgba(0,0,0,0) 100%)',
            transform: `translate(-50%, -50%) scale(${0.94 + panelOpacity * 0.08})`,
          }}
        />
      </div>
    </div>
  );
}

function WorkTransitionContent({
  reducedMotion,
  localizedEmails,
}: {
  reducedMotion: boolean;
  localizedEmails: typeof EMAIL_ENTRIES;
}) {
  const progress = useScrollStore((state) => state.workTransitionProgress);
  const stackAlign = reducedMotion
    ? 1
    : ease(
        clamp(
          (progress - CYCLE_MOTION.workTransition.stackAlignStart) /
            (CYCLE_MOTION.workTransition.stackAlignEnd -
              CYCLE_MOTION.workTransition.stackAlignStart),
          0,
          1,
        ),
      );
  const cardMorph = reducedMotion
    ? 1
    : ease(
        clamp(
          (progress - CYCLE_MOTION.workTransition.cardMorphStart) /
            (CYCLE_MOTION.workTransition.cardMorphEnd -
              CYCLE_MOTION.workTransition.cardMorphStart),
          0,
          1,
        ),
      );
  const contentSwap = reducedMotion
    ? 1
    : ease(
        clamp(
          (progress - CYCLE_MOTION.workTransition.contentSwapStart) /
            (CYCLE_MOTION.workTransition.contentSwapEnd -
              CYCLE_MOTION.workTransition.contentSwapStart),
          0,
          1,
        ),
      );
  const titleFade = reducedMotion
    ? 1
    : ease(
        clamp(
          (progress - CYCLE_MOTION.workTransition.titleFadeStart) /
            (CYCLE_MOTION.workTransition.titleFadeEnd -
              CYCLE_MOTION.workTransition.titleFadeStart),
          0,
          1,
        ),
      );
  const studies = CASE_STUDIES.slice(0, 3);

  return (
    <div className="relative flex h-full flex-col items-center justify-center px-6">
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          opacity: 0.88 - contentSwap * 0.72,
          background:
            'radial-gradient(circle at 50% 28%, rgba(255,231,208,0.18) 0%, rgba(190,59,73,0.18) 24%, rgba(97,17,29,0.28) 55%, rgba(0,0,0,0) 78%)',
        }}
      />
      <div className="relative w-full max-w-[72rem]">
        <div className="flex flex-col items-center gap-4">
          {studies.map((study, index) => {
            const email = localizedEmails[index] ?? localizedEmails[localizedEmails.length - 1];
            const briefing = LAPTOP_BRIEFING_META[index] ?? LAPTOP_BRIEFING_META[LAPTOP_BRIEFING_META.length - 1];
            const stackedY = reducedMotion ? 0 : (1 - stackAlign) * (index * -34);
            const width = 560 + cardMorph * 240;
            const height = 92 + cardMorph * 102;
            const border =
              contentSwap > 0.5
                ? 'rgba(255,255,255,0.08)'
                : 'rgba(255,231,208,0.12)';
            const bg =
              contentSwap > 0.5
                ? 'rgba(12,12,13,0.82)'
                : 'rgba(91,22,34,0.58)';
            const shadow =
              contentSwap > 0.5
                ? '0_24px_90px_rgba(0,0,0,0.35)'
                : '0_18px_48px_rgba(54,8,16,0.26)';

            return (
              <div
                key={study.slug}
                className="relative w-full max-w-[50rem] overflow-hidden rounded-[2rem] px-6 py-5"
                style={{
                  transform: `translateY(${stackedY}px) scale(${0.965 + cardMorph * 0.035})`,
                  width: `min(100%, ${width}px)`,
                  minHeight: `${height}px`,
                  border: `1px solid ${border}`,
                  background: bg,
                  boxShadow: shadow.replace(/_/g, ' '),
                  backdropFilter: 'blur(12px)',
                }}
              >
                <div className="absolute inset-0 bg-[radial-gradient(circle_at_18%_20%,rgba(224,68,88,0.12),rgba(0,0,0,0)_36%)]" />
                <div className="relative flex h-full items-start justify-between gap-6">
                  <div
                    className="max-w-[36rem]"
                    style={{
                      opacity: 1 - contentSwap,
                      transform: `translateY(${contentSwap * -10}px)`,
                    }}
                  >
                    <p className="font-mono text-[11px] uppercase tracking-[0.22em] text-[#ffe2bc]/76">
                      {`${briefing.section} • ${briefing.status}`}
                    </p>
                    <h3 className="mt-3 font-heading text-[clamp(1.4rem,3vw,2.4rem)] font-bold leading-[0.95] text-[#fff4e8]">
                      {email.subject}
                    </h3>
                    <p className="mt-3 max-w-[34rem] text-sm leading-relaxed text-[#ffe7cf]/72 md:text-base">
                      {email.preview}
                    </p>
                  </div>
                  <div
                    className="max-w-[36rem]"
                    style={{
                      opacity: contentSwap,
                      transform: `translateY(${(1 - contentSwap) * 12}px)`,
                      position: contentSwap > 0 ? 'absolute' : 'static',
                      inset: 0,
                    }}
                  >
                    <p className="font-mono text-[11px] uppercase tracking-[0.22em] text-accent/82">
                      {`0${index + 1} • ${study.sector}`}
                    </p>
                    <h3 className="mt-3 font-heading text-[clamp(1.4rem,3vw,2.5rem)] font-bold leading-[0.95] text-white">
                      {study.title.replace('\n', ' ')}
                    </h3>
                    <p className="mt-3 max-w-[34rem] text-sm leading-relaxed text-white/64 md:text-base">
                      {study.tagline}
                    </p>
                  </div>
                  <div className="shrink-0">
                    <div
                      className="rounded-full border px-4 py-2 font-mono text-[10px] uppercase tracking-[0.2em]"
                      style={{
                        borderColor:
                          contentSwap > 0.5 ? 'rgba(224,68,88,0.14)' : 'rgba(255,231,208,0.12)',
                        background:
                          contentSwap > 0.5 ? 'rgba(224,68,88,0.08)' : 'rgba(255,255,255,0.06)',
                        color: contentSwap > 0.5 ? 'rgba(224,68,88,0.82)' : 'rgba(255,236,214,0.82)',
                      }}
                    >
                      {contentSwap > 0.5 ? study.number : briefing.priority}
                    </div>
                    <p
                      className="mt-3 text-right font-mono text-[10px] uppercase tracking-[0.16em]"
                      style={{
                        opacity: 0.68,
                        color: contentSwap > 0.5 ? 'rgba(255,255,255,0.54)' : 'rgba(255,231,208,0.68)',
                      }}
                    >
                      {contentSwap > 0.5 ? study.shortOutcome : email.time}
                    </p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div
        className="mt-12 text-center"
        style={{
          opacity: titleFade,
          transform: reducedMotion ? 'none' : `translateY(${(1 - titleFade) * 24}px)`,
        }}
      >
        <p className="font-mono text-xs uppercase tracking-[0.24em] text-text-tertiary">
          {CYCLE_WORK_TRANSITION.sectionLabel}
        </p>
        <h3 className="mt-4 font-heading text-[clamp(2.2rem,5vw,4.4rem)] font-bold leading-[0.96] text-text-primary">
          {CYCLE_WORK_TRANSITION.headline}
          <br />
          <span className="italic text-text-primary/86">{CYCLE_WORK_TRANSITION.subline}</span>
        </h3>
      </div>
    </div>
  );
}

export default function CycleSection() {
  const sectionRef = useRef<HTMLDivElement>(null);
  const cycleBgColor = useScrollStore((state) => state.cycleBgColor);
  const { canRender3D } = useGPUCapability();
  const reducedMotion = useReducedMotion();
  const { visitorCity, visitorTZ } = useLiveClock();

  useScrollPhase(sectionRef);

  const safeVisitorTZ = getCycleVisitorTimeZone(visitorTZ || DEFAULT_VISITOR_TZ);
  const safeVisitorCity =
    visitorCity && visitorTZ && visitorTZ !== 'Asia/Bangkok'
      ? visitorCity
      : getCycleVisitorCity(visitorTZ || DEFAULT_VISITOR_TZ) || DEFAULT_VISITOR_CITY;
  const visitorTimeSequence = useMemo(
    () => getVisitorTimeSequence(BKK_TIME_SEQUENCE, safeVisitorTZ),
    [safeVisitorTZ],
  );
  const localizedEmails = useMemo(
    () => localizeEmailEntries(EMAIL_ENTRIES, safeVisitorTZ),
    [safeVisitorTZ],
  );
  const shouldRenderPhone3D = canRender3D && PHONE_3D_APPROVED;
  const laptopProgress = useScrollStore((state) => state.laptopProgress);
  const laptopReceiveIn = reducedMotion
    ? 1
    : ease(clamp(laptopProgress / CYCLE_MOTION.laptop.labelInEnd, 0, 1));

  return (
    <section
      ref={sectionRef}
      data-cycle-section
      className="relative"
      id="timeline"
      aria-label="The 24-Hour Cycle"
      data-concierge-section="timeline"
      data-concierge-label="The 24-Hour Cycle"
      style={{ height: `${SCROLL_TRIGGER_DEFAULTS.cycleScrollDistance * 100}vh` }}
    >
      <div
        className="sticky top-0 flex h-dvh items-center justify-center overflow-hidden"
        style={{ backgroundColor: cycleBgColor, willChange: 'background-color' }}
      >
        <CycleAtmosphere />

        <PhaseLayer phase="statement" reducedMotion={reducedMotion}>
          <StatementContent reducedMotion={reducedMotion} />
        </PhaseLayer>

        <PhaseLayer phase="handoff" reducedMotion={reducedMotion}>
          <HandoffContent
            reducedMotion={reducedMotion}
            visitorCity={safeVisitorCity}
            visitorTimeSequence={visitorTimeSequence}
          />
        </PhaseLayer>

        <PhaseLayer phase="logIntro" reducedMotion={reducedMotion}>
          <LogIntroContent reducedMotion={reducedMotion} />
        </PhaseLayer>

        <PhaseLayer phase="phone" reducedMotion={reducedMotion}>
          <PhoneContent reducedMotion={reducedMotion} />
          <div className="relative z-10 h-full w-full">
            {shouldRenderPhone3D ? (
              <ErrorBoundary fallback={<PhoneStage reducedMotion={reducedMotion} />}>
                <PhoneScene reducedMotion={reducedMotion} />
              </ErrorBoundary>
            ) : (
              <PhoneStage reducedMotion={reducedMotion} />
            )}
          </div>
        </PhaseLayer>

        <PhaseLayer phase="clock" reducedMotion={reducedMotion}>
          <ClockContent reducedMotion={reducedMotion} />
          {canRender3D ? (
            <ErrorBoundary fallback={<ClockFallback reducedMotion={reducedMotion} />}>
              <ClockScene reducedMotion={reducedMotion} />
            </ErrorBoundary>
          ) : (
            <ClockFallback reducedMotion={reducedMotion} />
          )}
        </PhaseLayer>

        <PhaseLayer phase="laptop" reducedMotion={reducedMotion}>
          <div
            className="relative z-10 h-full w-full"
            style={{
              opacity: laptopReceiveIn,
              transform: reducedMotion
                ? 'none'
                : `translateY(${(1 - laptopReceiveIn) * 22}px) scale(${0.982 + laptopReceiveIn * 0.018})`,
            }}
          >
            <LaptopSequenceLayer
              canRender3D={canRender3D}
              reducedMotion={reducedMotion}
              localizedEmails={localizedEmails}
            />
          </div>
        </PhaseLayer>

        <PhaseLayer phase="workTransition" reducedMotion={reducedMotion}>
          <WorkTransitionContent
            reducedMotion={reducedMotion}
            localizedEmails={localizedEmails}
          />
        </PhaseLayer>
      </div>
    </section>
  );
}
